(function () {
  'use strict';
  const {projects, sources} = globalThis.MediaInfoProjects;
  const C = globalThis.MediaInfoProjectsCore, L = globalThis.MediaInfoLearning, e = C.escape;
  const ACCESS_KEY = 'mediainfolab_student_access_v1', PREFIX = 'mediainfolab_projects_v1:';
  let state = C.empty(), owner = '', storageKey = '', storageOK = true, filter = 'Alle', pendingImport = null, pendingRoute = null, toastTimer;
  const $ = s => document.querySelector(s);
  const rfor = p => C.record(state,p);
  const W=globalThis.MediaInfoWorkspace({rfor,change,render,dialog,toast,download,backup,state:()=>state,owner:()=>owner});
  const icons = {
    play:'<rect x="8" y="13" width="64" height="46" rx="6"/><path d="m34 26 19 11-19 11z"/><path d="M16 68h48"/>',
    grid:'<rect x="9" y="9" width="62" height="62" rx="7"/><path d="M9 30h62M39 30v41M9 51h30M48 43h14M48 51h14M48 59h9"/>',
    file:'<path d="M24 8h27l14 14v49H24zM51 8v16h14M32 36h24M32 46h24M32 56h17"/><path d="M16 17H9v55"/>',
    search:'<circle cx="34" cy="32" r="22"/><path d="m50 49 22 22M34 19v18M34 42v3"/>',
    bolt:'<path d="M45 5 16 45h23l-5 30 30-44H43z"/>'
  };
  const icon = p => `<svg viewBox="0 0 80 80" aria-hidden="true">${icons[p.icon] || icons.file}</svg>`;
  const list = (items,cls='') => `<ul${cls?` class="${e(cls)}"`:''}>${items.map(x=>`<li>${e(x)}</li>`).join('')}</ul>`;
  const pill = r => `<span class="status-pill ${r.finishedAt?'done':C.status(r)==='In Arbeit'?'working':''}">${C.status(r)}</span>`;
  function note(p,key,label,placeholder='') {
    return `<label class="note-label" for="note-${e(key)}">${e(label)}</label><textarea class="project-note" id="note-${e(key)}" data-note="${e(key)}" data-project="${p.id}" maxlength="12000" placeholder="${e(placeholder)}">${e(rfor(p).notes[key]||'')}</textarea>`;
  }
  function visibleActions(p,r,actions) {
    const choice = r.choice || p.choices?.[0]?.id;
    if(!choice) return actions;
    const prefixes=p.id==='dokumente'?{scan:'Scanweg:',bilder:'Bildweg:'}:p.id==='tutorial'?{bilder:'Bildanleitung:',video:'Video:'}:null;
    if(!prefixes) return actions;
    return actions.flatMap(a=>a.split(/(?=Scanweg:|Bildweg:|Bildanleitung:|Video:|Für ein Video:)/).filter(Boolean)).filter(a=>{
      const match=Object.entries(prefixes).find(([,prefix])=>a.startsWith(prefix));
      if(a.startsWith('Für ein Video:')) return choice==='video';
      return !match || match[0]===choice;
    });
  }
  function resources(p){return p.resources?`<h3>Ihr Übungsmaterial</h3><p>Öffnen Sie die Dateien in einem neuen Tab. Alle Angaben sind erfundene Übungsdaten.</p><div class="resource-list">${p.resources.map(x=>`<a class="p-button" href="${e(x.href)}" target="_blank" rel="noopener">${e(x.label)} ↗</a>`).join('')}</div>`:'';}
  function sourceList(p){return `<details class="project-sources"><summary>${p.id==='faktencheck'?'Quellenhilfen für Ihre Recherche':'Offizielle Hilfen und Quellen'}</summary><p>Die folgenden Seiten öffnen in einem neuen Tab. Menüs können je nach Gerät und Programmversion anders heissen.</p><ul class="source-list">${sources.filter(s=>s.projects.includes(p.id)).map(s=>`<li><a href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.label)} ↗</a></li>`).join('')}</ul>${p.id==='dokumente'?'<p><a href="index.html#scan-guide" target="_blank" rel="noopener">Scan-Guide auf dieser Webseite öffnen ↗</a></p>':''}</details>`;}
  function pause(p){return `<div class="project-handoff"><strong>Für heute gut abschliessen</strong><p>Halten Sie Ihren Speicherort und den nächsten Handgriff im Cockpit fest.</p><button class="p-button" type="button" data-action="lesson-close" data-project="${p.id}">Etappe sichern und Wiedereinstieg merken</button></div>`;}
  function catalogue() {
    const active=projects.filter(p=>C.status(rfor(p))==='In Arbeit').sort((a,b)=>rfor(b).updatedAt.localeCompare(rfor(a).updatedAt));
    const shown=projects.filter(p=>filter==='Alle'||p.category===filter); const extras=(globalThis.MediaInfoKurzprojekte||[]).filter(p=>filter==='Alle'||p.category===filter);
    return `<section class="project-hero"><div><p class="eyebrow">Projekte · Ihre Werkstatt</p><h1>Ein Plan für heute.<br>Etwas Eigenes für morgen.</h1><p class="hero-line">Entdecken Sie ein Projekt, das Sie interessiert. Ihr Cockpit hilft beim Planen, die Werkbank beim Umsetzen – bis zu einem Ergebnis, das Sie zeigen können.</p><p>9 Projekte · freie Themenwahl · kurze und ausführliche Aufträge</p><a class="p-button light" href="#${active[0]?.id||projects[0].id}${active.length?'/cockpit':''}">${active.length?'Mein Projekt weiterplanen':'Ein erstes Projekt entdecken'} →</a></div><div class="cockpit-illustration" aria-label="Ihr Arbeitsweg: Zeit planen, umsetzen, testen und für die nächste Lektion sichern"><div class="illustration-top"><span class="assistant-mark">✦</span><strong>Ihr Projekt-Assistent</strong><span class="live-dot"></span></div><div class="illustration-today"><small>HEUTE</small><strong>Ein klarer nächster Schritt.</strong><div class="illustration-bars"><span></span><span></span><span></span></div><p>Zeit für Pflichtarbeit, Projekt und Abschluss.</p></div><div class="illustration-next"><span>↳</span><div><small>NÄCHSTE LEKTION</small><strong>Wissen, wo es weitergeht.</strong><p>Offene Schritte und eigener Merksatz.</p></div></div></div></section>
    <div class="journey-strip"><div><b>01</b><span><strong>Wählen</strong>Ein Projekt, das Sie interessiert.</span></div><div><b>02</b><span><strong>Planen</strong>Ihre Zeit sinnvoll einteilen.</span></div><div><b>03</b><span><strong>Umsetzen</strong>Vorlage und Schritte nutzen.</span></div><div><b>04</b><span><strong>Sichern</strong>Testen und den Wiedereinstieg merken.</span></div></div>
    ${active.length?`<section class="continue-panel"><p class="eyebrow">Ihr bisheriger Stand bleibt erhalten</p><h2>Hier können Sie weiterarbeiten</h2><div class="continue-grid">${active.map(p=>`<div><strong>${e(p.title)}</strong><p>${rfor(p).checks.length}/${p.steps.length} Schritte geprüft${rfor(p).planner.nextAction?' · '+e(rfor(p).planner.nextAction):''}</p><a class="p-button primary" href="#${p.id}/cockpit">Meine nächste Etappe planen →</a></div>`).join('')}</div></section>`:''}
    <div class="catalogue-head"><div><p class="eyebrow">Sie entscheiden</p><h2 id="viewTitle" tabindex="-1">Was möchten Sie entwickeln?</h2></div><div class="filters" role="group" aria-label="Projekte nach Interesse filtern">${['Alle','Erklären','Organisieren','Prüfen','Entdecken','Gestalten'].map(x=>`<button id="filter-${e(x)}" type="button" data-filter="${e(x)}" aria-pressed="${filter===x}">${x}</button>`).join('')}</div></div>
    <p id="filterCount" class="note-hint" role="status">${shown.length+extras.length} von ${projects.length+(globalThis.MediaInfoKurzprojekte||[]).length} Projekten · Wählen Sie zunächst eines und führen Sie es zu einem brauchbaren Ergebnis.</p>
    <div class="notice"><strong>Woche 44:</strong> Nach Ihrer vollständigen Prüfungsabgabe dürfen Sie ohne zusätzliche Absprache selbst wählen. <a href="woche44.html">Die Anleitung für heute öffnen →</a><br>Die vier kurzen Projekte bearbeiten und sichern Sie direkt auf ihrer jeweiligen Seite. Die Schaltflächen «Arbeitsstand sichern» und «Sicherung laden» hier in der Übersicht gehören zu den fünf ausführlichen Projekten.</div><div class="project-grid">${extras.map(p=>`<article class="project-card"><div class="miniart ${p.color}"><span>${e(p.icon)}</span><small>PROJEKT ${p.number} · ${e(p.category)}</small></div><div class="card-body"><h3><a href="projekt.html?thema=${p.id}">${e(p.title)}</a></h3><p>${e(p.hook)}</p><p class="card-product"><strong>Das entsteht</strong>${e(p.product)}</p><p>${e(p.duration)} · Zusatzaufträge vorhanden</p><a class="p-button primary" href="projekt.html?thema=${p.id}">Auftrag und Arbeitsfelder öffnen →</a></div></article>`).join('')}${shown.map(p=>{const r=rfor(p);return `<article class="project-card tone-${p.color}"><a class="card-cover" href="#${p.id}" tabindex="-1" aria-hidden="true"><img src="assets/projects/media/${p.id}-02.svg" alt="" width="1280" height="720" loading="lazy"><span>${p.number} · ${e(p.category)}</span></a><div class="card-body"><h3><a href="#${p.id}">${e(p.title)}</a></h3><p class="card-subtitle">${e(p.subtitle)}</p><p>${e(p.hook)}</p><p class="card-product"><strong>Das entsteht</strong>${e(p.product)}</p><div class="card-meta"><span>${e(p.duration)}</span><span>·</span><span>${p.steps.length} Schritte</span></div><div class="card-bottom"><a class="project-link" href="#${p.id}">Kurzübersicht öffnen →</a>${pill(r)}</div><a class="video-card-link" href="#${p.id}/beispiele">▷ Beispielvideo und Bildfolge ansehen</a></div></article>`}).join('')}</div>
    <section class="catalogue-help"><h2>Gut starten und selbstständig weiterkommen</h2><details><summary>Wann darf ich ein Projekt beginnen?</summary><p>In Woche 44 dürfen Sie nach der vollständigen Prüfungsabgabe selbst wählen. Für andere Wochen gelten die jeweiligen Wochenaufträge. Das Cockpit bezieht den heutigen Klassenfokus ein. Offene Pflichtarbeit bekommt zuerst Zeit. Sie müssen nicht alle neun Projekte bearbeiten.</p></details><details><summary>Was passiert, wenn eine Lektion nicht reicht?</summary><p>Das ist eingeplant. Das Cockpit zeigt eine passende Etappe und den voraussichtlichen Rest. Am Schluss notieren Sie den nächsten Handgriff und Ihren Speicherort. Beim nächsten Mal planen Sie mit den noch offenen Schritten weiter.</p></details><details><summary>Wo liegen meine Arbeit und meine Sicherung?</summary><p>Häkchen, Planung, Notizen und Werkbank-Inhalte mit eingefügten Bildern werden in diesem Browser gespeichert, getrennt nach eingegebener Schulmail. Es gibt keine automatische Synchronisation der Projekte zwischen Geräten.</p><p>Wählen Sie vor dem Gerätewechsel «Arbeitsstand sichern» und legen Sie die JSON-Datei in OneDrive ab. Auf dem anderen Gerät: gleiche Schulmail, dann «Sicherung laden». Externe Produktdateien wie Aufnahmen, Scan-PDFs und OneNote-Seiten speichern Sie zusätzlich in OneDrive.</p></details><details><summary>Wie gebe ich mein Ergebnis ab?</summary><p>Speichern Sie Ihr Produkt unter «OneDrive → Informatik → Projekte → Projektname». Zeigen Sie es Herrn Marti oder geben Sie es in einer vorhandenen Teams-Aufgabe ab. Ein Häkchen auf dieser Seite sendet noch keine Datei.</p></details><details><summary>Wie nutze ich Beispiele und Hilfen sinnvoll?</summary><p>Schauen Sie ein passendes Beispiel an, wählen Sie eine Vorlage und führen Sie den nächsten kleinen Arbeitsschritt selbst aus. Klappen Sie zusätzliche Erklärungen nur bei Bedarf auf. KI kann beim Nachdenken helfen; selbst ausprobieren, prüfen und erklären gehört zu Ihrer Arbeit. Verwenden Sie keine privaten Angaben anderer Personen.</p></details></section>`;
  }
  function shell(p,page,index,content){
    const r=rfor(p),tabs=[['overview','','Überblick'],['planner','/cockpit','Mein Cockpit'],['studio','/werkbank','Meine Werkbank'],['media','/beispiele','Video & Beispiele']];
    return `<div class="tone-${p.color}"><nav class="crumbs" aria-label="Pfad"><a href="projekte.html">Projekte</a><span aria-hidden="true">/</span><a href="#${p.id}">${e(p.title)}</a>${page==='step'?`<span aria-hidden="true">/</span><span>Schritt ${index+1}</span>`:''}</nav><header class="project-heading"><p class="eyebrow">Projekt ${p.number} · ${e(p.category)}</p><h1>${e(p.title)}</h1><p>${e(p.subtitle)}</p></header><nav class="project-route-tabs" aria-label="Arbeitsbereiche">${tabs.map(([v,path,label])=>`<a href="#${p.id}${path}" ${page===v?'aria-current="page"':''}>${label}</a>`).join('')}</nav><div class="project-layout"><aside class="project-sidebar"><p class="side-title">Ihr Weg zum Ergebnis</p><progress value="${r.checks.length}" max="${p.steps.length}" aria-label="Erledigte Projektschritte"></progress><p class="side-progress">${r.checks.length} von ${p.steps.length} Schritten geprüft</p><details class="step-menu" ${globalThis.matchMedia?.('(min-width: 851px)').matches!==false?'open':''}><summary>Die 6 Arbeitsschritte</summary><nav aria-label="Projektschritte">${p.steps.map((s,i)=>`<a href="#${p.id}/schritt-${i+1}" ${page==='step'&&index===i?'aria-current="page"':''}><span class="step-number ${r.checks.includes(i)?'checked':''}" aria-label="${r.checks.includes(i)?'erledigt':'offen'}">${r.checks.includes(i)?'✓':i+1}</span><span>${e(s.title)}</span></a>`).join('')}<a href="#${p.id}/abschluss" ${page==='finish'?'aria-current="page"':''}><span class="step-number ${r.finishedAt?'checked':''}">${r.finishedAt?'✓':'→'}</span><span>Prüfen & abschliessen</span></a></nav></details><div class="side-tools"><a href="#${p.id}/cockpit">Zeit und Folgelektion planen</a><button type="button" data-action="lesson-close" data-project="${p.id}">Für heute aufhören</button><button type="button" data-action="print" data-project="${p.id}">Ganzer Auftrag / Drucken</button><button type="button" data-action="pass" data-project="${p.id}">Mein Projektpass als Text</button></div></aside><div class="project-content">${['step','studio','finish'].includes(page)?`<div id="liveAssistant">${W.summary(p)}</div>`:''}${content}${sourceList(p)}</div></div></div>`;
  }
  function toolbox(p){return p.toolbox?`<section class="content-panel toolbox"><h2>Trickauswahl: direkt ausprobieren</h2><p>Wählen Sie 5 verschiedene Tricks. Öffnen Sie nur die Anleitungen, die Sie gerade brauchen.</p>${p.toolbox.map(t=>`<details><summary>${e(t.title)}</summary><div><p>${e(t.how)}</p><p><strong>Ihr Test:</strong> ${e(t.test)}</p></div></details>`).join('')}</section>`:'';}
  function overview(p){
    const r=rfor(p),choice=r.choice||p.choices?.[0]?.id;
    return shell(p,'overview',-1,`<section class="content-panel"><p class="eyebrow">Zuerst die Kurzübersicht</p><h2 id="viewTitle" tabindex="-1">Darum geht es</h2><p class="overview-summary">${e(p.summary)}</p><dl class="project-facts"><div><dt>Ihr Ergebnis</dt><dd>${e(p.product)}</dd></div><div><dt>Zeit für den Basisauftrag</dt><dd>${e(p.duration)} · auf mehrere Etappen verteilbar</dd></div><div><dt>Arbeitsform</dt><dd>${e(p.work)}</dd></div><div><dt>Das lernen Sie</dt><dd>${e(p.learn)}</dd></div></dl><details class="visual-detail"><summary>Was brauche ich für dieses Projekt?</summary>${list(p.needs)}</details><div class="p-actions"><a class="p-button primary" href="#${p.id}/cockpit">Meine erste oder nächste Etappe planen →</a><a class="p-button" href="#${p.id}/beispiele">▷ Beispiele ansehen</a>${pill(r)}</div></section><section class="content-panel"><h2>So sieht ein brauchbares Ergebnis aus</h2>${W.figure(p,1)}<p>${e(p.exampleIntro)}</p><div class="p-actions"><a class="p-button" href="#${p.id}/werkbank">Passende Vorlage auswählen →</a><a class="project-link" href="#${p.id}/beispiele">Alle Beispiele mit Erklärung</a></div></section><section class="content-panel"><h2>Ihre Idee und Ihr Arbeitsweg</h2>${p.choices?`<div class="route-options">${p.choices.map(c=>`<label class="route-option"><input type="radio" id="choice-${c.id}" name="workRoute" data-choice="${c.id}" data-project="${p.id}" ${choice===c.id?'checked':''}><span><strong>${e(c.label)}</strong><small>${e(c.description)}</small></span></label>`).join('')}</div><p class="note-hint">Die Schrittanleitungen passen sich an Ihre Wahl an.</p>`:''}<details class="visual-detail"><summary>Ich suche noch eine Idee</summary><div class="idea-list">${p.ideas.map(([t,d])=>`<div class="idea"><strong>${e(t)}</strong><p>${e(d)}</p></div>`).join('')}</div></details>${note(p,'plan','Mein Thema in einem Satz (freiwillig)','Was möchten Sie entwickeln?')}<div class="first-move"><strong>Der erste konkrete Handgriff</strong>${e(p.start)}</div>${resources(p)}</section>${toolbox(p)}<section class="content-panel"><h2>Das gehört zum fertigen Basisauftrag</h2>${list(p.quality)}<p>Das Cockpit plant diese Arbeit über Ihre Lektionen. Die Werkbank hilft bei der Gestaltung. Am Schluss prüfen Sie Ihr tatsächliches Produkt.</p><div class="p-actions"><a class="p-button primary" href="#${p.id}/cockpit">Meine Lektion planen →</a><a class="p-button" href="#${p.id}/${C.next(r,p)}">Direkt zum nächsten Auftrag</a></div></section>`);
  }
  function stepView(p,index){
    const r=rfor(p),s=p.steps[index],acts=visibleActions(p,r,s.actions),selected=p.choices?.find(c=>c.id===(r.choice||p.choices[0].id)),first=acts.findIndex((_,i)=>!r.actions.includes(`${index}-${i}`));
    const illustrations={tutorial:[0,4,1,2,5,6],cockpit:[0,1,2,3,5,6],dokumente:[6,1,4,0,5,6],faktencheck:[0,1,4,2,5,6],lifehacks:[0,1,2,3,6,7]};
    return shell(p,'step',index,`<section class="content-panel step-panel"><div class="step-topline"><span>Schritt ${index+1} von ${p.steps.length}</span><span>Richtwert: ${e(s.minutes)}</span></div><h2 id="viewTitle" tabindex="-1">${e(s.title)}</h2><p class="step-goal">${e(s.goal)}</p>${selected?`<p class="note-hint">Ihr Weg: <strong>${e(selected.label)}</strong> · <a href="#${p.id}">ändern</a></p>`:''}<div class="step-shortcuts"><a href="#${p.id}/werkbank">▦ Meine Vorlage bearbeiten</a><a href="#${p.id}/beispiele">▷ Beispielvideo</a><a href="#${p.id}/cockpit">◷ Meine Zeit planen</a></div><h3>Jetzt nacheinander ausführen</h3><p class="note-hint">Jede Karte ist eine kleine Teilaufgabe. Die zusätzliche Erklärung hilft bei der genauen Umsetzung. Die kleinen Häkchen sind Ihre Gedächtnisstütze.</p><div class="action-cards">${acts.map((x,i)=>{const match=/^(.*?[.!?])(?:\s+|$)([\s\S]*)/.exec(x),lead=match?match[1]:x,more=match?match[2]:'';return `<article class="action-card ${r.actions.includes(`${index}-${i}`)?'is-checked':''}"><label for="micro-${index}-${i}"><input id="micro-${index}-${i}" type="checkbox" data-micro="${index}-${i}" data-project="${p.id}" ${r.actions.includes(`${index}-${i}`)?'checked':''}><span><small>Teilaufgabe ${i+1}</small><strong>${e(lead)}</strong></span></label>${more?`<details ${i===first?'open':''}><summary>Genauer erklärt</summary><p>${e(more)}</p></details>`:''}</article>`;}).join('')}</div><div class="step-example-grid"><div><h3>So wird es konkret</h3><div class="example-box"><p>${e(s.example)}</p></div></div>${W.figure(p,illustrations[p.id][index],true)}</div><div class="help-section"><h3>Wenn Sie an dieser Stelle feststecken</h3>${s.help.map(h=>`<details><summary>${e(h.question)}</summary><p>${e(h.answer)}</p></details>`).join('')}</div>${p.id==='dokumente'&&index<3?resources(p):''}${p.id==='lifehacks'&&index<2?toolbox(p):''}<label class="checkpoint" for="stepCheck"><input id="stepCheck" type="checkbox" data-step="${index}" data-project="${p.id}" ${r.checks.includes(index)?'checked':''}><span><strong>Schritt erst nach dem Ergebnischeck abschliessen</strong>${e(s.checkpoint)}</span></label><details class="step-note"><summary>Eine Notiz oder offene Frage festhalten</summary>${note(p,`step${index}`,'Meine Notiz','Was möchte ich mir merken?')}</details><div class="step-nav"><a class="p-button" href="#${p.id}${index?`/schritt-${index}`:''}">← ${index?'Vorheriger Schritt':'Kurzübersicht'}</a><a class="p-button primary" href="#${p.id}/${index===p.steps.length-1?'abschluss':`schritt-${index+2}`}">${index===p.steps.length-1?'Zur Qualitätskontrolle':'Nächsten Schritt ansehen'} →</a></div><p class="note-hint">Weitergehen setzt kein Ergebnis-Häkchen. Wenn die Zeit knapp wird: <button type="button" class="inline-button" data-action="lesson-close" data-project="${p.id}">Etappe sichern und nächsten Einstieg merken</button>.</p></section>`);
  }
  function finishView(p) {
    const r=rfor(p), eligible=C.eligible(r,p), missing=p.steps.length-r.checks.length;
    return shell(p,'finish',-1,`<section class="content-panel"><p class="eyebrow">Ergebnis vorzeigen können</p><h2 id="viewTitle" tabindex="-1">Prüfen Sie Ihre Arbeit</h2><p>Öffnen Sie Ihr tatsächliches Produkt. Haken Sie nur ab, was Sie daran überprüft haben. Die Webseite bewertet die Qualität nicht automatisch.</p>${missing?`<p class="finish-hint">Noch ${missing} ${missing===1?'Schritt ist':'Schritte sind'} offen. <a href="#${p.id}/${C.next(r,p)}">Zum ersten offenen Schritt →</a></p>`:''}<div class="quality-list">${p.quality.map((q,i)=>`<label class="quality-item" for="quality-${i}"><input type="checkbox" id="quality-${i}" data-quality="${i}" data-project="${p.id}" ${r.quality.includes(i)?'checked':''}><span>${e(q)}</span></label>`).join('')}</div>${note(p,'result','Was habe ich gelernt oder verbessert? (freiwillig)','Ein konkreter Satz genügt.')}<p><a class="project-link" href="#${p.id}/werkbank">Meine Werkbank zum Gegenprüfen öffnen →</a></p><h3>Speichern und abgeben</h3><p>Speichern Sie Ihr Produkt im schulischen OneDrive unter <strong>Informatik → Projekte → Projektname</strong>. Zeigen Sie es Herrn Marti oder geben Sie es in einer vorhandenen Teams-Aufgabe ab. Das Häkchen hier sendet keine Datei an die Lehrperson.</p>${r.finishedAt?'<div class="finish-banner"><strong>Basisauftrag fertig – nach Ihrer eigenen Kontrolle.</strong><p>Sie können eine Vertiefung wählen oder ein weiteres Projekt beginnen.</p></div>':`<p id="finishRequirement" class="note-hint">${eligible?'Alle Schritte und Qualitätskriterien sind abgehakt.':`Für den Abschluss fehlen noch ${missing} Schritte und ${p.quality.length-r.quality.length} Qualitätskriterien.`}</p><button class="p-button primary" type="button" data-action="finish" data-project="${p.id}" aria-describedby="finishRequirement" ${eligible?'':'disabled'}>Basisauftrag als fertig markieren</button>`}<div class="p-actions"><button class="p-button" type="button" data-action="pass" data-project="${p.id}">Mein Projektpass als Text</button><button class="p-button" type="button" data-action="backup">Arbeitsstand sichern</button></div><p class="note-hint">Der Projektpass enthält Ihren Stand und Ihre Notizen. Das eigentliche Produkt speichern und zeigen Sie zusätzlich.</p></section><section class="content-panel"><p class="eyebrow">Freiwillig weiterdenken</p><h2>Noch Zeit und Lust?</h2><p>Wenn Ihr Basisauftrag fertig ist, wählen Sie eine Vertiefung. Hier geht es inhaltlich einen Schritt weiter.</p>${p.extensions.map(x=>`<article class="extension"><h3>${e(x.title)}</h3><span class="duration">${e(x.time)}</span><p>${e(x.text)}</p></article>`).join('')}<a class="project-link" href="projekte.html">Alle Projekte ansehen →</a>${pause(p)}</section>`);
  }
  function printView(p) {
    const r=rfor(p);
    return `<header><p>MedienInfoLab · Projekte · BFF Bern</p><h1>${e(p.title)}</h1><p>${e(p.subtitle)}</p></header><div class="print-meta"><p>${e(p.summary)}</p><p><strong>Ergebnis:</strong> ${e(p.product)}</p><p><strong>Zeit:</strong> ${e(p.duration)} · ${e(p.work)}</p><p><strong>Stand:</strong> ${C.status(r)} · ${r.checks.length}/${p.steps.length} Schritte</p></div><section><h2>Vorbereitung</h2>${list(p.needs)}<p><strong>Ihr erster Schritt:</strong> ${e(p.start)}</p><h3>Wenig Zeit?</h3>${list(Object.values(p.timeboxes))}<h3>Ihre Idee</h3><p class="print-note">${e(r.notes.plan||'Noch keine Notiz.')}</p>${p.resources?`<h3>Übungsmaterial</h3>${list(p.resources.map(x=>x.label+' · https://mediainfolab.com/'+x.href))}`:''}</section>${p.steps.map((s,i)=>`<section class="print-step"><h2>Schritt ${i+1}: ${e(s.title)}</h2><p>${e(s.goal)} · ${e(s.minutes)}</p><ol>${visibleActions(p,r,s.actions).map(x=>`<li>${e(x)}</li>`).join('')}</ol><p><strong>Beispiel:</strong> ${e(s.example)}</p>${s.help.map(h=>`<h3>${e(h.question)}</h3><p>${e(h.answer)}</p>`).join('')}<p><strong>${r.checks.includes(i)?'Erledigt':'Noch offen'}:</strong> ${e(s.checkpoint)}</p>${r.notes[`step${i}`]?`<h3>Meine Notiz</h3><p class="print-note">${e(r.notes[`step${i}`])}</p>`:''}</section>`).join('')}<section class="print-step"><h2>Qualitätskontrolle</h2>${list(p.quality.map((q,i)=>(r.quality.includes(i)?'[x] ':'[ ] ')+q))}<h3>Meine Erkenntnis</h3><p class="print-note">${e(r.notes.result||'Noch keine Notiz.')}</p><h3>Nächstes Mal</h3><p class="print-note">${e(r.notes.pause||'Noch keine Notiz.')}</p><h2>Freiwillige Vertiefungen</h2>${p.extensions.map(x=>`<h3>${e(x.title)} · ${e(x.time)}</h3><p>${e(x.text)}</p>`).join('')}<h2>Vorlage</h2><p class="print-note">${e(p.template)}</p>${p.toolbox?`<h2>Trickauswahl</h2>${p.toolbox.map(t=>`<h3>${e(t.title)}</h3><p>${e(t.how)}</p><p>${e(t.test)}</p>`).join('')}`:''}<h2>Quellen und Hilfen</h2>${list(sources.filter(s=>s.projects.includes(p.id)).map(s=>s.label+' · '+s.url))}</section>`;
  }
  function warn(message) {storageOK=false; const el=$('#storageWarning');if(el){el.hidden=false;el.textContent=message;}saveLabel();}
  function saveLabel(){const el=$('#saveStatus');if(el)el.textContent=storageOK?'Arbeitsstand: lokal in diesem Browser':'Nicht dauerhaft gespeichert – Sicherung herunterladen';}
  function account() {
    let email='';try{email=String(JSON.parse(localStorage.getItem(ACCESS_KEY)||'{}').email||'').trim().toLowerCase();}catch{}
    if(!/^(?:[^\s@]+@stud\.bffbern\.ch|christoph\.marti@bffbern\.ch)$/.test(email))email='';
    if(email===owner)return;
    owner=email;pendingImport=null;pendingRoute=null;W.reset();if($('#projectDialog').open)$('#projectDialog').close();storageKey=owner?PREFIX+owner:'';state=C.empty();storageOK=true;
    $('#storageWarning').hidden=true;
    if(storageKey){try{const raw=localStorage.getItem(storageKey);if(raw)state=C.normalize(JSON.parse(raw),projects);}catch{warn('Ihr gespeicherter Projektstand lässt sich nicht lesen oder der Browserspeicher ist blockiert. Neue Eingaben bleiben vorläufig nur in dieser Sitzung. Sichern Sie sie vor dem Schliessen als Datei.');}}
    saveLabel();render(false);W.loadFocus();
  }
  function change(p, fn) {
    if(!owner){toast('Bitte geben Sie zuerst Ihre Schulmail ein.');return;}
    if(storageOK){try{const raw=localStorage.getItem(storageKey);if(raw)state=C.normalize(JSON.parse(raw),projects);}catch{warn('Der Browserspeicher ist nicht verfügbar. Sichern Sie Ihren Stand vor dem Schliessen als Datei.');}}
    const now=new Date().toISOString(),r=C.cleanProject(rfor(p),p),beforeStudio=JSON.stringify(r.studio);fn(r);
    if(beforeStudio!==JSON.stringify(r.studio)){r.quality=[];r.finishedAt='';}
    r.studio=L.cleanStudio(r.studio);r.planner=L.cleanPlanner(r.planner);
    if(!C.eligible(r,p))r.finishedAt='';
    r.updatedAt=now;state.projects[p.id]=r;state.updatedAt=now;
    if(storageOK){try{localStorage.setItem(storageKey,JSON.stringify(state));}catch{warn('Der Browser konnte die Änderung nicht dauerhaft speichern. Ihre Eingaben bleiben in dieser Sitzung. Laden Sie jetzt eine Sicherung herunter.');}}
    saveLabel();
  }
  function toast(message){const el=$('#projectToast');el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,5000);}
  function render(moveFocus=true){
    const active=document.activeElement,oldId=active?.id,y=globalThis.scrollY||0;
    const r=C.route(location.hash,projects);
    $('#main').innerHTML=!r.project?catalogue():r.page==='overview'?overview(r.project):r.page==='step'?stepView(r.project,r.index):r.page==='planner'?shell(r.project,'planner',-1,W.plannerView(r.project)):r.page==='studio'?shell(r.project,'studio',-1,W.studioView(r.project)+W.undoButton(r.project)):r.page==='media'?shell(r.project,'media',-1,W.mediaView(r.project)):finishView(r.project);
    document.title=r.project?`${r.project.title} · Projekte · MedienInfoLab`:'Projekte · MedienInfoLab';
    if(moveFocus){$('#viewTitle')?.focus({preventScroll:true});if(r.project&&globalThis.matchMedia?.('(max-width: 850px)').matches)$('#viewTitle')?.scrollIntoView?.({block:'start'});else globalThis.scrollTo?.(0,0);}else if(oldId){document.getElementById(oldId)?.focus({preventScroll:true});globalThis.scrollTo?.(0,y);}
  }
  function download(name,content,type='text/plain;charset=utf-8') {
    const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
  }
  function backup(){if(!owner){toast('Bitte geben Sie zuerst Ihre Schulmail ein.');return;}const stamp=new Date().toISOString().replace(/[:.]/g,'-');download(`MedienInfoLab-Projekte-${stamp}.json`,C.encode(state,projects,owner),'application/json');toast('Sicherung erstellt. Sie enthält Planung, Häkchen und Ihre Werkbank mit Bildern. Speichern Sie externe Produktdateien zusätzlich in OneDrive.');}
  function dialog(title,body,size=''){const d=$('#projectDialog');d.setAttribute('data-size',size);$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=body;if(!d.open)d.showModal();}
  function projectPass(p){const r=rfor(p);return `${p.title}\n${p.subtitle}\n\nStand: ${C.status(r)}\n${r.checks.length} von ${p.steps.length} Schritten\n\nMEINE IDEE\n${r.notes.plan||'–'}\n\n${p.steps.map((s,i)=>`${r.checks.includes(i)?'[x]':'[ ]'} Schritt ${i+1}: ${s.title}\n${r.notes[`step${i}`]||''}`).join('\n\n')}\n\nQUALITÄTSCHECK\n${p.quality.map((q,i)=>`${r.quality.includes(i)?'[x]':'[ ]'} ${q}`).join('\n')}\n\nMEINE ERKENNTNIS / VERBESSERUNG\n${r.notes.result||'–'}\n\nNÄCHSTER SCHRITT\n${r.planner.nextAction||r.notes.pause||'–'}\n\nSPEICHERORT\n${r.planner.file||'Noch nicht festgehalten'}\n\nGEPLANTE FOLGELEKTION\n${r.planner.nextDate||'Noch kein Datum'} · ${r.planner.nextMinutes} Minuten\n\nDieser Pass enthält keine Produktdateien. PDF, Video oder OneNote-Ergebnis zusätzlich speichern und zeigen.\n`;}
  function setLarge(on){document.documentElement.classList.toggle('portal-large',on);$('#projectFont').setAttribute('aria-pressed',String(on));$('#projectFont').textContent=on?'A−':'A+';try{const ui=JSON.parse(localStorage.getItem('informatikPortal_ui_v1')||'{}');localStorage.setItem('informatikPortal_ui_v1',JSON.stringify({...ui,largeText:on}));}catch{}}
  function start(){
    account();render(false);W.init();try{setLarge(!!JSON.parse(localStorage.getItem('informatikPortal_ui_v1')||'{}').largeText);}catch{}
    $('#projectFont').addEventListener('click',()=>setLarge(!document.documentElement.classList.contains('portal-large')));
    document.addEventListener('submit',()=>account());
    document.addEventListener('input',event=>{const el=event.target,p=projects.find(p=>p.id===el.dataset?.project);if(p&&W.handleInput(el,p))return;if(p&&el.dataset.note){change(p,r=>{r.notes[el.dataset.note]=el.value.slice(0,12000);r.startedAt ||= new Date().toISOString();});}});
    document.addEventListener('change',event=>{
      const el=event.target,p=projects.find(p=>p.id===el.dataset?.project);if(!p)return;
      if(W.handleChange(el,p))return;
      if(el.dataset.micro){change(p,r=>{r.actions=el.checked?[...new Set([...r.actions,el.dataset.micro])]:r.actions.filter(x=>x!==el.dataset.micro);r.startedAt ||= new Date().toISOString();});render(false);return;}
      if(el.hasAttribute('data-step')||el.hasAttribute('data-quality')){const key=el.hasAttribute('data-step')?'checks':'quality',i=Number(el.dataset.step??el.dataset.quality);change(p,r=>{r[key]=el.checked?[...new Set([...r[key],i])]:r[key].filter(x=>x!==i);r.startedAt ||= new Date().toISOString();});render(false);}
      if(el.dataset.choice){const r=rfor(p),choice=el.dataset.choice;if(choice===(r.choice||p.choices?.[0]?.id))return;if(r.checks.length||r.quality.length){pendingRoute={project:p.id,choice,owner};dialog('Arbeitsweg wechseln?',`<p>Der neue Weg hat andere Arbeitsschritte. Deshalb werden beim Wechsel die Schritt- und Qualitäts-Häkchen dieses Projekts zurückgesetzt. Ihre Notizen, Planung und Werkbank bleiben erhalten.</p><div class="p-actions"><button class="p-button" type="button" data-action="backup">Jetzigen Stand zuerst sichern</button><button class="p-button primary" type="button" data-action="confirm-route" data-project="${p.id}">Arbeitsweg wechseln und Häkchen zurücksetzen</button></div>`);}else change(p,x=>{x.choice=choice;x.actions=[];});render(false);}
    });
    document.addEventListener('click',async event=>{
      const button=event.target.closest('button');if(!button)return;
      if(button.dataset.filter){filter=button.dataset.filter;render(false);return;}
      const p=projects.find(p=>p.id===button.dataset.project);
      if(await W.handleClick(button,p))return;
      if(button.dataset.time&&p){change(p,r=>{r.time=button.dataset.time;});render(false);return;}
      switch(button.dataset.action){
        case 'start': if(p){change(p,r=>{r.startedAt ||= new Date().toISOString();r.choice ||= p.choices?.[0]?.id||'';});location.hash=`${p.id}/${rfor(p).finishedAt?'abschluss':'cockpit'}`;}break;
        case 'finish': if(p&&C.eligible(rfor(p),p)){change(p,r=>{r.finishedAt=new Date().toISOString();});render(false);toast('Basisauftrag als fertig markiert. Denken Sie daran, Ihr Produkt zu zeigen oder abzugeben.');}break;
        case 'backup': backup();break;
        case 'import': $('#importProjectFile').value='';$('#importProjectFile').click();break;
        case 'close-dialog': $('#projectDialog').close();pendingImport=null;pendingRoute=null;render(false);break;
        case 'confirm-route': if(pendingRoute?.project===p?.id&&pendingRoute.owner===owner){change(p,r=>{r.choice=pendingRoute.choice;r.actions=[];r.checks=[];r.quality=[];r.finishedAt='';});pendingRoute=null;$('#projectDialog').close();render(false);}break;
        case 'confirm-import': if(pendingImport&&storageKey){state=pendingImport;pendingImport=null;try{localStorage.setItem(storageKey,JSON.stringify(state));storageOK=true;$('#storageWarning').hidden=true;}catch{warn('Die Sicherung wurde in diese Sitzung geladen. Der Browser kann sie aber nicht dauerhaft speichern. Behalten Sie Ihre Sicherungsdatei.');}$('#projectDialog').close();saveLabel();render(false);toast('Projektstand aus der Sicherung übernommen.');}break;
        case 'storage-help':dialog('Wo wird was gespeichert?','<p><strong>Ihr Produkt:</strong> Speichern Sie PDF, Video, Präsentation oder OneNote-Seite im schulischen OneDrive.</p><p><strong>Auf dieser Webseite:</strong> Planung, Häkchen, Notizen und Ihre Werkbank mit eingefügten Bildern werden lokal in diesem Browser gespeichert, getrennt nach der eingegebenen Schulmail. Sie werden nicht automatisch auf ein anderes Gerät oder in den Lehrpersonenbereich übertragen.</p><p><strong>Gerät wechseln:</strong> «Arbeitsstand sichern», Datei in OneDrive ablegen, am anderen Gerät dieselbe Schulmail verwenden und «Sicherung laden» wählen.</p><p>Das Löschen der Browserdaten kann den lokalen Stand entfernen. Die Projekt-Sicherung enthält die Werkbank mit Bildern; externe Videos, Scan-PDFs und OneNote-Seiten sichern Sie zusätzlich. Die Eingabe der Schulmail ist keine Passwortsperre; verwenden Sie für persönliche Arbeit Ihr eigenes Browserprofil.</p>');break;
        case 'template':if(p)location.hash=`${p.id}/werkbank`;break;
        case 'copy-template':{const field=$('#templateText');try{await navigator.clipboard.writeText(field.value);toast('Vorlage kopiert. Fügen Sie sie jetzt in Ihr Arbeitsprogramm ein.');}catch{field.focus();field.select();toast('Der Text ist markiert. Kopieren Sie mit Ctrl + C oder Cmd + C.');}break;}
        case 'download-template':if(p)download(`${p.id}-Projektvorlage.txt`,p.template);break;
        case 'pass':if(p)download(`${p.id}-Mein-Projektpass.txt`,projectPass(p));break;
        case 'print':if(p){$('#printProject').innerHTML=printView(p);globalThis.print();}break;
      }
    });
    $('#importProjectFile').addEventListener('change',async event=>{
      const file=event.target.files?.[0];if(!file)return;
      try{if(!owner)throw new Error('Bitte geben Sie zuerst Ihre Schulmail ein.');if(file.size>6000000)throw new Error('Diese Datei ist zu gross für eine Projektsicherung.');pendingImport=C.decode(await file.text(),projects,owner);const n=Object.keys(pendingImport.projects).length;dialog('Sicherung übernehmen?',`<p>Datei: <strong>${e(file.name)}</strong></p><p>Enthält ${n} Projektstände. Die Übernahme ersetzt Ihre jetzige Projektplanung, Häkchen, Notizen und Werkbank-Inhalte mit Bildern in diesem Browser. Andere Workshops und Ihre Produktdateien werden nicht verändert.</p><div class="p-actions"><button class="p-button" type="button" data-action="backup">Jetzigen Stand zuerst sichern</button><button class="p-button primary" type="button" data-action="confirm-import">Diese Sicherung übernehmen</button></div>`);}catch(error){pendingImport=null;toast(error.message);}
    });
    globalThis.addEventListener('focus',()=>W.loadFocus());
    globalThis.addEventListener('hashchange',()=>{if($('#projectDialog').open)$('#projectDialog').close();pendingImport=null;render(true);});
    globalThis.addEventListener('storage',event=>{if(event.key===ACCESS_KEY){account();return;}if(event.key===storageKey){try{state=event.newValue?C.normalize(JSON.parse(event.newValue),projects):C.empty();render(false);}catch{warn('Ein anderer Tab hat einen unlesbaren Stand gespeichert. Ihre aktuellen Eingaben bleiben in dieser Sitzung.');}}});
  }
  // Pure markup entry points also support automated structural checks without a browser.
  globalThis.MediaInfoProjectViews={catalogue,overview,stepView,finishView,printView,visibleActions,planner:p=>shell(p,'planner',-1,W.plannerView(p)),studio:p=>shell(p,'studio',-1,W.studioView(p)),media:p=>shell(p,'media',-1,W.mediaView(p))};
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();
